use builder_config::ServerConfigBuilder;

#[test]
fn test_defaults() {
    let cfg = ServerConfigBuilder::new().build().unwrap();
    assert_eq!(cfg.host, "localhost");
    assert_eq!(cfg.port, 8080);
    assert_eq!(cfg.max_connections, 100);
    assert!(!cfg.debug);
}

#[test]
fn test_custom_values() {
    let cfg = ServerConfigBuilder::new()
        .host("example.com")
        .port(9090)
        .max_connections(500)
        .debug(true)
        .build()
        .unwrap();
    assert_eq!(cfg.host, "example.com");
    assert_eq!(cfg.port, 9090);
    assert_eq!(cfg.max_connections, 500);
    assert!(cfg.debug);
}

#[test]
fn test_invalid_port_zero() {
    let result = ServerConfigBuilder::new().port(0).build();
    assert!(result.is_err());
}

#[test]
fn test_empty_host_rejected() {
    let result = ServerConfigBuilder::new().host("").build();
    assert!(result.is_err());
}

#[test]
fn test_method_chain() {
    // chaining works without intermediate bindings
    let _ = ServerConfigBuilder::new().host("a").port(80).debug(false).build().unwrap();
}
